// Agent Workflow plugin for MiMo Code (generated by agent-workflow sync; do not edit).
// Adds the project-gated reminder to the system prompt. No commands, network, project code or
// transcript access; opted-out projects get nothing.
import {hookResult} from '__AW_GATE_URL__';

export const AgentWorkflow=async({directory}={})=>({
  'experimental.chat.system.transform':async(_input,output)=>{
    let text;
    try{text=hookResult({cwd:directory??process.cwd(),hook_event_name:'SessionStart'}).hookSpecificOutput?.additionalContext;}catch{return;}
    if(text&&Array.isArray(output?.system)&&!output.system.includes(text))output.system.push(text);
  },
});
